// Orders v2 through PayPal's official Server SDK (@paypal/paypal-server-sdk), generated by APIMatic
// (see the "automatically generated by APIMATIC v3.0" header in its src/client.ts).
// The SDK covers create, get and capture with a PayPal-Request-Id. Order tracking (its createOrderTracking
// takes no PayPal-Request-Id) and Disputes v1 (no controller in the SDK) stay on the client in ./paypal.ts.
import { ApiError, Client, Environment, OrdersController, type ApiResponse, type Order, type OrderRequest } from '@paypal/paypal-server-sdk';
import { PayPalError } from './paypal.ts';

export function ordersApi(httpOverrides?: Record<string, unknown>) {
  const oAuthClientId = process.env.PAYPAL_CLIENT_ID;
  const oAuthClientSecret = process.env.PAYPAL_CLIENT_SECRET;
  if (!oAuthClientId || !oAuthClientSecret) throw new Error(`Missing PayPal configuration: ${[!oAuthClientId && 'PAYPAL_CLIENT_ID', !oAuthClientSecret && 'PAYPAL_CLIENT_SECRET'].filter(Boolean).join(', ')}`);
  return new OrdersController(new Client({
    clientCredentialsAuthCredentials: { oAuthClientId, oAuthClientSecret },
    environment: process.env.PAYPAL_ENV === 'live' ? Environment.Production : Environment.Sandbox,
    timeout: 30_000,
    unstable_httpClientOptions: httpOverrides,
  }));
}
let shared: OrdersController | undefined;
const orders = () => (shared ??= ordersApi());

// Callers keep PayPal's own JSON field names (purchase_units, payer_action links) for read-back checks.
async function raw(operation: string, call: () => Promise<ApiResponse<Order>>): Promise<any> {
  try {
    const response = await call();
    return typeof response.body === 'string' && response.body ? JSON.parse(response.body) : response.result;
  } catch (error) {
    if (!(error instanceof ApiError)) throw error;
    const debugId = Object.entries(error.headers ?? {}).find(([key]) => key.toLowerCase() === 'paypal-debug-id')?.[1] ?? null;
    console.error('PayPal request failed', { status: error.statusCode, debugId, operation });
    throw new PayPalError(`PayPal request failed (${error.statusCode})${debugId ? `, debug ${debugId}` : ''}`, error.statusCode, debugId);
  }
}

export const createOrder = (body: OrderRequest, requestId: string, api = orders()) =>
  raw('orders.create', () => api.createOrder({ body, paypalRequestId: requestId, prefer: 'return=representation' }));
export const getOrder = (id: string, api = orders()) =>
  raw('orders.get', () => api.getOrder({ id }));
export const captureOrder = (id: string, requestId: string, api = orders()) =>
  raw('orders.capture', () => api.captureOrder({ id, paypalRequestId: requestId, prefer: 'return=representation' }));
